style.css:
@-moz-document domain("wikipedia.org") {
/* 1. FONDO DE WIKIPEDIA: Rosa Pastel con Círculos Blancos Pequeños */
    body, 
    html, 
    #content, 
    .mw-page-container, 
    #mw-head, 
    #mw-panel, 
    #footer, 
    .mw-sidebar,
    .vector-page-container,
    .vector-header-container,
    [style*="background-color"] {
        background-color: #FFDEE9 !important; /* Tu hermoso Rosa Pastel de base */
        background-image: radial-gradient(#FFFFFF 12%, transparent 12%),
                          radial-gradient(#FFFFFF 12%, transparent 12%) !important;
        background-size: 24px 24px !important; /* Lunares pequeños y estéticos */
        background-position: 0 0, 12px 12px !important;
        background-attachment: fixed !important;
    }

    /* Limpieza de fondos blancos rebeldes de la enciclopedia */
    .mw-body, .parsoid-body, #content, .vector-menu-content-list, .vector-settings {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* 2. TEXTOS Y ARTÍCULOS: Letras Café Clarito y Cursivas Legibles */
    h1, h2, h3, h4, h5, h6, p, span, div, li, dt, dd, th, td, .mw-body-content {
        color: #A0522D !important; /* Tu Café Clarito bien bonito */
        font-family: 'Georgia', 'Lucida Handwriting', cursive !important; /* Cursiva que se entiende perfecto */
        font-style: italic !important;
        /* Delineado blanco muy fino para que el café se lea perfecto sobre el rosa */
        text-shadow: -1px -1px 0 #FFFFFF, 1px -1px 0 #FFFFFF, -1px 1px 0 #FFFFFF, 1px 1px 0 #FFFFFF !important;
    }

    /* Los enlaces (links) de Wikipedia ahora serán café clarito también */
    a, a:link, a:visited, .vector-menu-portal .vector-menu-content a {
        color: #A0522D !important;
        text-decoration: underline !important; /* Mantiene la línea abajo para saber qué es un link */
    }

    /* 3. LOGO DE WIKIPEDIA: Amarillo Pastel Tierno */
    /* Volvemos invisible el mundo de metal gris original */
    .mw-wiki-logo, .vector-header-logo img, [alt="Wikipedia"] {
        opacity: 0 !important;
    }
    /* Ponemos un globo terráqueo estilizado en un hermoso Amarillo Pastel */
    .mw-wiki-logo, .vector-header-logo {
        background-image: url('https://icons8.com') !important; /* Ícono de planeta tierno */
        background-size: contain !important;
        background-repeat: no-repeat !important;
        background-position: center !important;
        filter: hue-rotate(20deg) brightness(1.2) sepia(0.6) saturate(1.8) !important; /* Truco mágico para pintarlo de amarillo pastel */
    }

    /* 4. BUSCADOR SUPERIOR E ICONOS: Rosa Pastel */
    #searchform, 
    .cdx-search-input, 
    .cdx-text-input__input, 
    #searchInput {
        background-color: #FFB7CE !important; /* Tu Rosa Pastel indicado */
        border: 2px solid #FFFFFF !important;
        border-radius: 20px !important;
        color: #FFFFFF !important; /* Letras blancas al escribir */
    }
    
    /* El texto de sugerencias que sale en el buscador */
    .cdx-text-input__input::placeholder {
        color: rgba(255, 255, 255, 0.8) !important;
    }

    /* Iconos generales (La lupita de buscar, las flechas y engranajes) */
    svg, path, .vector-icon, .cdx-button {
        fill: #FFB7CE !important; /* Rosa Pastel */
        color: #FFB7CE !important;
    }
}
